  "asana/resources/get_portfolios.yml": "type: resource\nname: get_portfolios\ndescription: List Asana portfolios scoped to each workspace\napi:\n  endpoint: /portfolios\n  method: GET\n  query_params:\n    workspace: ${{ input.workspace_gid }}\n    limit: ${{ input.limit }}\n    offset: ${{ input.offset }}\ninput:\n  workspace_gid:\n    type: string\n    description: Asana workspace GID used to scope the portfolio list\n    required: true\n  limit:\n    type: integer\n    description: Number of portfolios to return per page\n    default: 100\n  offset:\n    type: string\n    description: Pagination cursor returned by the previous response\noutput:\n  gid:\n    type: string\n    path: $.gid\n    description: Asana portfolio identifier\n  name:\n    type: string\n    path: $.name\n    description: Portfolio name\n  resource_type:\n    type: string\n    path: $.resource_type\n    description: Asana resource type\n  workspace_gid:\n    type: string\n    path: $.workspace.gid\n    description: GID of the workspace containing the portfolio\n  workspace_name:\n    type: string\n    path: $.workspace.name\n    description: Name of the workspace containing the portfolio\nextract:\n  record_path: $.data\n  pagination:\n    type: cursor\n    cursor_path: $.next_page.offset\n    cursor_param: offset\n  for_each:\n    resource: get_workspaces\n    field: gid\n    input: workspace_gid\n  table:\n    primary_key:\n      - gid\n    trust_tier: silver\n",
